messages.content:
Tool response:
Tool: insert_clauses_into_contract
Description: Insert Clauses Into Contract
Parameters:
    {
      "type": "object",
      "properties": {
        "contract_ref": {
          "type": "string",
          "description": "Unique reference identifier of the draft contract",
          "title": "Contract Ref"
        },
        "__body__": {
          "type": "array",
          "items": {
            "properties": {
              "clause_title": {
                "type": "string",
                "title": "Clause Title"
              },
              "insert_after": {
                "anyOf": [
                  {
                    "type": "integer"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Insert After"
              }
            },
            "type": "object",
            "required": [
              "clause_title"
            ],
            "title": "ClauseInsertItem"
          },
          "title": "Clauses"
        }
      },
      "required": [
        "contract_ref",
        "__body__"
      ]
    }
